import{w as p}from"./index-BhN5TsxC.js";import{w as d}from"./withTimeout-DaiEZiXe.js";function w(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Manila",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date)}const u=[{topic:"General Science & Biology",difficulty:"medium"},{topic:"World History & Global Civilizations",difficulty:"medium"},{topic:"Mathematics & Logic Reasoning",difficulty:"hard"},{topic:"Computer Science & Digital Systems",difficulty:"medium"},{topic:"Physics & Fundamental Forces",difficulty:"medium"},{topic:"Chemistry & Molecular Sciences",difficulty:"medium"},{topic:"Economics, Markets & Society",difficulty:"easy"},{topic:"Neuroscience & Cognitive Psychology",difficulty:"medium"},{topic:"Environmental Science & Climate",difficulty:"easy"},{topic:"Literature & Critical Analysis",difficulty:"medium"}],m={0:[{question:"Which metabolic process produces the greatest net yield of ATP per glucose molecule in aerobic respiration?",options:["A. Glycolysis","B. Citric Acid Cycle (Krebs)","C. Oxidative Phosphorylation","D. Lactic Acid Fermentation"],correct_answer:"C",explanation:"Oxidative phosphorylation via the electron transport chain and ATP synthase yields approximately 26–28 ATP per glucose."},{question:"In DNA replication, which enzyme is responsible for unwinding the double helix at the replication fork?",options:["A. DNA Polymerase III","B. Helicase","C. Topoisomerase","D. Ligase"],correct_answer:"B",explanation:"DNA Helicase breaks the hydrogen bonds between complementary base pairs to unwind the double helix."},{question:"During which mitotic phase do sister chromatids separate toward opposite poles of the cell?",options:["A. Prophase","B. Metaphase","C. Anaphase","D. Telophase"],correct_answer:"C",explanation:"During Anaphase, cohesin proteins are cleaved, allowing sister chromatids to be pulled toward opposing spindle poles."},{question:"What is the primary function of ribulose-1,5-bisphosphate carboxylase-oxygenase (RuBisCO)?",options:["A. Photolysis of water in Photosystem II","B. Carbon dioxide fixation in the Calvin cycle","C. Synthesis of NADPH in light reactions","D. Electron transfer along the cytochrome b6f complex"],correct_answer:"B",explanation:"RuBisCO catalyzes the primary carbon fixation reaction incorporating atmospheric CO2 into RuBP in the stroma."},{question:"Which cellular organelle possesses its own circular DNA and double membrane supporting the endosymbiotic theory?",options:["A. Golgi Apparatus","B. Endoplasmic Reticulum","C. Mitochondrion","D. Lysosome"],correct_answer:"C",explanation:"Mitochondria contain their own mDNA and bacterial-like 70S ribosomes, supporting the endosymbiotic origin hypothesis."}],1:[{question:"Which document established the principle of limited monarchical power in England in 1215?",options:["A. The English Bill of Rights","B. The Magna Carta","C. The Petition of Right","D. The Treaty of Westphalia"],correct_answer:"B",explanation:"The Magna Carta was signed by King John at Runnymede in 1215, establishing that the sovereign is subject to the rule of law."},{question:"The ancient Silk Road facilitated trade and cultural exchange primarily between which two regions?",options:["A. Northern Europe and Sub-Saharan Africa","B. China and the Mediterranean World","C. Mesoamerica and the Andean Highlands","D. Japan and Southeast Asia"],correct_answer:"B",explanation:"The Silk Road was an extensive network of trade routes connecting East Asia through Central Asia to the Mediterranean Basin."},{question:"Which peace treaty in 1648 is recognized as founding the modern system of sovereign nation-states?",options:["A. Treaty of Utrecht","B. Peace of Westphalia","C. Congress of Vienna","D. Treaty of Versailles"],correct_answer:"B",explanation:"The Peace of Westphalia ended the Thirty Years' War and established state sovereignty and non-interference norms."},{question:"Johannes Gutenberg's movable-type printing press was first commercially deployed in which decade?",options:["A. 1380s","B. 1450s","C. 1520s","D. 1580s"],correct_answer:"B",explanation:"Gutenberg introduced movable metal type around 1440 and published the 42-line Gutenberg Bible in Mainz around 1455."},{question:"Which ancient civilization constructed the cliff dwellings and kivas at Mesa Verde?",options:["A. Ancestral Puebloans (Anasazi)","B. Mississippian Culture","C. Maya Civilization","D. Aztec Empire"],correct_answer:"A",explanation:"The Ancestral Puebloans built the multi-story cliff dwellings in southwestern Colorado during the 12th and 13th centuries."}],2:[{question:"What is the derivative of f(x) = ln(3x^2 + 1) with respect to x?",options:["A. 6x / (3x^2 + 1)","B. 1 / (3x^2 + 1)","C. 6x * (3x^2 + 1)","D. 3 / (3x^2 + 1)"],correct_answer:"A",explanation:"By the chain rule, d/dx[ln(u)] = u'/u. Here u = 3x^2 + 1, so u' = 6x, yielding 6x / (3x^2 + 1)."},{question:"If a 3x3 matrix A has determinant det(A) = 4, what is det(2A)?",options:["A. 8","B. 16","C. 32","D. 64"],correct_answer:"C",explanation:"For an n x n matrix, det(k*A) = k^n * det(A). Here n=3, so 2^3 * 4 = 8 * 4 = 32."},{question:"In propositional logic, what is the logical negation of the statement: 'Every integer is positive'?",options:["A. Every integer is negative","B. No integer is positive","C. There exists at least one integer that is not positive","D. All integers are zero or negative"],correct_answer:"C",explanation:"The negation of a universal quantifier (∀x P(x)) is the existential negation: ∃x ¬P(x)."},{question:"How many distinct permutations can be formed from the letters of the word 'SUCCESS'?",options:["A. 420","B. 840","C. 2,520","D. 5,040"],correct_answer:"A",explanation:"7 letters with 3 S's and 2 C's: 7! / (3! * 2!) = 5040 / (6 * 2) = 5040 / 12 = 420."},{question:"What is the limit of (sin 3x) / x as x approaches 0?",options:["A. 0","B. 1","C. 3","D. Undefined"],correct_answer:"C",explanation:"Using lim_{u->0} (sin u)/u = 1, rewrite as 3 * (sin 3x)/(3x) -> 3 * 1 = 3."}],3:[{question:"What is the average-case time complexity of searching for an element in a balanced binary search tree (AVL / Red-Black)?",options:["A. O(1)","B. O(log n)","C. O(n)","D. O(n log n)"],correct_answer:"B",explanation:"In balanced search trees, height is maintained at O(log n), providing O(log n) lookup, insertion, and deletion."},{question:"Which layer of the OSI reference model is responsible for end-to-end flow control and reliable data segmentation?",options:["A. Network Layer (Layer 3)","B. Transport Layer (Layer 4)","C. Data Link Layer (Layer 2)","D. Session Layer (Layer 5)"],correct_answer:"B",explanation:"The Transport Layer (TCP, UDP) handles host-to-host communication, packet sequencing, and flow control."},{question:"In relational database design, what normal form requires eliminating partial functional dependencies on composite candidate keys?",options:["A. First Normal Form (1NF)","B. Second Normal Form (2NF)","C. Third Normal Form (3NF)","D. Boyce-Codd Normal Form (BCNF)"],correct_answer:"B",explanation:"2NF requires 1NF plus all non-prime attributes to be fully functionally dependent on every candidate key."},{question:"In memory management, what is the primary difference between Stack and Heap allocation?",options:["A. The Stack is dynamically managed by the programmer; the Heap is strictly LIFO","B. The Stack follows LIFO managed automatically by the compiler; the Heap allows dynamic arbitrary allocations","C. The Stack has unlimited size; the Heap is limited to 1MB","D. The Heap is stored in CPU registers; the Stack is on secondary storage"],correct_answer:"B",explanation:"Stack memory is scoped to activation frames with automatic push/pop; heap memory is allocated dynamically at runtime."},{question:"Which cryptographic algorithm is based on the computational difficulty of finding discrete logarithms in elliptic curve groups?",options:["A. RSA","B. ECDSA","C. AES-256","D. SHA-3"],correct_answer:"B",explanation:"ECDSA (Elliptic Curve Digital Signature Algorithm) relies on the Elliptic Curve Discrete Logarithm Problem (ECDLP)."}],4:[{question:"According to Faraday's Law of Electromagnetic Induction, the induced electromotive force (EMF) is proportional to:",options:["A. The magnitude of the magnetic field alone","B. The time rate of change of magnetic flux","C. The electrical resistance of the loop","D. The electrostatic potential difference"],correct_answer:"B",explanation:"Faraday's law states that EMF = -dΦ_B/dt, meaning induced voltage equals the rate of change of magnetic flux through the circuit."},{question:"What physical phenomenon occurs when light waves pass through a narrow slit and spread into the geometric shadow region?",options:["A. Total Internal Reflection","B. Polarization","C. Diffraction","D. Photoelectric Effect"],correct_answer:"C",explanation:"Diffraction is the bending and interference of wave fronts as they encounter an obstacle or aperture comparable in size to their wavelength."},{question:"Which thermodynamic law states that the entropy of an isolated system never decreases over time?",options:["A. Zeroth Law","B. First Law","C. Second Law","D. Third Law"],correct_answer:"C",explanation:"The Second Law of Thermodynamics dictates that natural processes increase the overall entropy of an isolated system."},{question:"What is the escape velocity formula from the surface of a spherical celestial body of mass M and radius R?",options:["A. v = sqrt(GM / R)","B. v = sqrt(2GM / R)","C. v = 2GM / R^2","D. v = GM / (2R)"],correct_answer:"B",explanation:"Equating kinetic energy (1/2 m v^2) to gravitational potential energy (G M m / R) yields v = sqrt(2GM/R)."},{question:"Which fundamental particle mediates the electromagnetic interaction between charged particles?",options:["A. Gluon","B. W/Z Boson","C. Photon","D. Graviton"],correct_answer:"C",explanation:"In the Standard Model, the massless gauge boson responsible for the electromagnetic force is the photon."}],5:[{question:"According to Le Chatelier's Principle, what happens to an exothermic equilibrium reaction (ΔH < 0) when the temperature is increased?",options:["A. The equilibrium shifts toward the products","B. The equilibrium shifts toward the reactants","C. The equilibrium constant K remains unchanged","D. The reaction rate drops to zero"],correct_answer:"B",explanation:"Heat is a product in exothermic reactions; increasing temperature shifts equilibrium toward reactants to absorb excess heat."},{question:"What is the hybridization and molecular geometry of the carbon atom in methane (CH4)?",options:["A. sp2, Trigonal Planar","B. sp3, Tetrahedral","C. sp, Linear","D. dsp3, Trigonal Bipyramidal"],correct_answer:"B",explanation:"Carbon forms 4 equivalent sigma bonds with bond angles of 109.5°, requiring sp3 orbital hybridization with tetrahedral geometry."},{question:"Which acid-base definition classifies a base specifically as an electron-pair donor?",options:["A. Arrhenius","B. Brønsted-Lowry","C. Lewis","D. Pearson Hard-Soft"],correct_answer:"C",explanation:"G.N. Lewis defined an acid as an electron-pair acceptor and a base as an electron-pair donor."},{question:"What is the oxidation state of chromium in the dichromate anion (Cr2O7^2-)?",options:["A. +3","B. +4","C. +6","D. +7"],correct_answer:"C",explanation:"7 oxygen atoms contribute -14. With an overall charge of -2: 2(Cr) - 14 = -2 => 2(Cr) = +12 => Cr = +6."},{question:"Which intermolecular force is primarily responsible for the anomalously high boiling point of water compared to hydrogen sulfide (H2S)?",options:["A. London Dispersion Forces","B. Hydrogen Bonding","C. Dipole-Induced Dipole","D. Ion-Dipole Forces"],correct_answer:"B",explanation:"Hydrogen bonding between electronegative oxygen atoms and hydrogen atoms creates strong intermolecular attractions in liquid water."}],6:[{question:"What economic concept describes the loss of potential gain from other alternatives when one alternative is chosen?",options:["A. Sunk Cost","B. Opportunity Cost","C. Marginal Revenue","D. Comparative Advantage"],correct_answer:"B",explanation:"Opportunity cost is the value of the next-best alternative forgone when making a decision."},{question:"If a 10% increase in the price of a good results in a 15% decrease in the quantity demanded, the price elasticity of demand is:",options:["A. Inelastic (0.67)","B. Unit Elastic (1.0)","C. Elastic (1.5)","D. Perfectly Inelastic (0.0)"],correct_answer:"C",explanation:"Elasticity = |%ΔQ / %ΔP| = 15% / 10% = 1.5. Since > 1, demand is elastic."},{question:"Which market structure is characterized by a single seller, high barriers to entry, and no close substitutes?",options:["A. Perfect Competition","B. Monopolistic Competition","C. Oligopoly","D. Monopoly"],correct_answer:"D",explanation:"A pure monopoly exists when one firm produces all output in a market protected by insurmountable barriers to entry."},{question:"When a central bank sells government securities in open market operations, what is the expected effect on the money supply and interest rates?",options:["A. Money supply expands, interest rates fall","B. Money supply contracts, interest rates rise","C. Money supply expands, interest rates rise","D. Money supply contracts, interest rates fall"],correct_answer:"B",explanation:"Selling bonds absorbs bank reserves, contracting the domestic money supply and driving up short-term borrowing interest rates."},{question:"Which component is NOT directly included in the expenditure approach to Gross Domestic Product (GDP = C + I + G + NX)?",options:["A. Gross Private Domestic Investment","B. Government Transfer Payments (Pensions/Unemployment)","C. Net Exports","D. Personal Consumption Expenditures"],correct_answer:"B",explanation:"Transfer payments are reallocations of wealth without current production of goods or services, and are excluded from GDP."}],7:[{question:"During an action potential in a mammalian neuron, the rapid depolarizing phase is primarily driven by:",options:["A. Outflow of potassium ions (K+)","B. Influx of sodium ions (Na+) through voltage-gated channels","C. Active transport by the sodium-potassium pump","D. Influx of chloride ions (Cl-)"],correct_answer:"B",explanation:"Reaching threshold triggers the opening of voltage-gated Na+ channels, causing rapid Na+ influx down its electrochemical gradient."},{question:"Which brain structure is critically required for the consolidation of declarative memories from short-term to long-term storage?",options:["A. Hippocampus","B. Cerebellum","C. Medulla Oblongata","D. Basal Ganglia"],correct_answer:"A",explanation:"The hippocampus and adjacent medial temporal lobe structures consolidate episodic and semantic memories for cortical storage."},{question:"In classical conditioning, what was the meat powder in Ivan Pavlov's famous salivation experiments with dogs?",options:["A. Conditioned Stimulus (CS)","B. Unconditioned Stimulus (UCS)","C. Conditioned Response (CR)","D. Neutral Stimulus (NS)"],correct_answer:"B",explanation:"The food naturally and automatically elicited salivation without prior training, making it an unconditioned stimulus."},{question:"Which neurotransmitter is primarily synthesized in the substantia nigra and lost in patients with Parkinson's disease?",options:["A. Serotonin","B. Acetylcholine","C. Dopamine","D. GABA"],correct_answer:"C",explanation:"Parkinson's disease involves progressive degeneration of dopaminergic neurons in the substantia nigra pars compacta."},{question:"According to George A. Miller's classic 1956 paper, what is the magical number representing working memory capacity?",options:["A. 3 ± 1","B. 7 ± 2","C. 12 ± 3","D. 15 ± 2"],correct_answer:"B",explanation:"Miller posited that human short-term memory can store roughly seven plus or minus two chunks of information."}],8:[{question:"Which atmospheric gas accounts for the largest natural greenhouse warming effect on Earth?",options:["A. Carbon Dioxide (CO2)","B. Methane (CH4)","C. Water Vapor (H2O)","D. Nitrous Oxide (N2O)"],correct_answer:"C",explanation:"Water vapor is the most abundant natural greenhouse gas, accounting for 60-70% of the natural greenhouse effect."},{question:"What term describes the ecological phenomenon where changes at the top of a food web cause cascading effects across lower trophic levels?",options:["A. Trophic Cascade","B. Primary Succession","C. Eutrophication","D. Biomagnification"],correct_answer:"A",explanation:"A trophic cascade occurs when apex predators regulate prey density and behavior, indirectly propagating down to primary producers."},{question:"What is the primary cause of cultural eutrophication in freshwater lakes and estuaries?",options:["A. Thermal pollution from nuclear power plants","B. Excessive runoff of nitrogen and phosphorus from fertilizers and wastewater","C. Acid precipitation dissolving heavy metals","D. Atmospheric carbon dioxide absorption"],correct_answer:"B",explanation:"Agricultural nutrient runoff over-enriches waters, sparking massive algal blooms that deplete dissolved oxygen upon decomposing."},{question:"Which layer of the atmosphere contains the protective ozone layer that absorbs harmful solar ultraviolet (UV-C and UV-B) radiation?",options:["A. Troposphere","B. Stratosphere","C. Mesosphere","D. Thermosphere"],correct_answer:"B",explanation:"The ozone layer resides in the stratosphere between roughly 15 km and 35 km above Earth's surface."},{question:"What term describes the gradual accumulation of persistent synthetic chemicals (like DDT or microplastics) at higher concentrations up the food chain?",options:["A. Bioaccumulation","B. Biomagnification","C. Bioremediation","D. Biodegradation"],correct_answer:"B",explanation:"Biomagnification is the escalating concentration of fat-soluble toxins in organisms at successively higher trophic levels."}],9:[{question:"What literary device is used when an author hints at future narrative plot developments before they occur?",options:["A. Foreshadowing","B. Anachronism","C. Dramatic Irony","D. Deus Ex Machina"],correct_answer:"A",explanation:"Foreshadowing gives readers subtle clues or warnings about events that will happen later in the story."},{question:"In classical Aristotelian tragedy, what is the term for the tragic flaw that causes the protagonist's downfall?",options:["A. Catharsis","B. Anagnorisis","C. Hamartia","D. Peripeteia"],correct_answer:"C",explanation:"Hamartia is the fatal flaw, judgment error, or character defect that initiates the protagonist's reversal of fortune."},{question:"Which poetic meter consists of five feet per line, with each foot containing an unstressed syllable followed by a stressed syllable?",options:["A. Trochaic Tetrameter","B. Dactylic Hexameter","C. Iambic Pentameter","D. Anapestic Trimeter"],correct_answer:"C",explanation:"Iambic pentameter features five iambs (da-DUM da-DUM da-DUM da-DUM da-DUM), common in Shakespearean sonnets and blank verse."},{question:"Which modernist narrative technique attempts to capture the unfiltered, continuous flow of a character's conscious thoughts and associations?",options:["A. Epistolary Format","B. Stream of Consciousness","C. Allegory","D. Picaresque Narrative"],correct_answer:"B",explanation:"Stream of consciousness mimics internal human cognition, famously employed by James Joyce and Virginia Woolf."},{question:"What figure of speech substitutes the name of an attribute or adjunct for that of the thing meant (e.g., 'the Crown' for royalty)?",options:["A. Synecdoche","B. Metonymy","C. Chiasmus","D. Oxymoron"],correct_answer:"B",explanation:"Metonymy refers to a concept by the name of something closely associated with it rather than its explicit name."}]};async function x(){var l;const t=w(),i=`pz_daily_challenge_${t}`;try{const a=localStorage.getItem(i);if(a){const e=JSON.parse(a);if(((l=e==null?void 0:e.questions)==null?void 0:l.length)>0)return e}}catch{}const[g,f,y]=t.split("-").map(Number),n=Math.abs(Math.floor(g*365+f*30+y)%u.length),{topic:o,difficulty:r}=u[n],s=m[n]||m[0];try{const a=p.from("daily_challenges").select("*").eq("challenge_date",t).maybeSingle(),{data:e}=await d(a,6e3,"daily_challenges query");if(e&&e.questions&&e.questions.length>0){const h={id:e.id||`daily-${t}`,challenge_date:t,topic:e.topic||o,difficulty:e.difficulty||r,questions:e.questions};try{localStorage.setItem(i,JSON.stringify(h))}catch{}return h}}catch(a){console.warn("[dailyChallenge] Supabase challenge fetch timed out or failed:",a)}const c={id:`daily-${t}`,challenge_date:t,topic:o,difficulty:r,questions:s};try{localStorage.setItem(i,JSON.stringify(c))}catch{}try{d(p.from("daily_challenges").insert({challenge_date:t,topic:o,questions:s}).select().maybeSingle(),2e3,"daily challenge background insert").catch(()=>{})}catch{}return c}export{x as g};
